import {
  Config,
  Context,
  Effect,
  Layer,
  Option,
  Redacted,
  Schema,
} from "effect";

import { SendblueConfigError } from "./errors.js";
import {
  E164PhoneNumber,
  SendblueConfig,
  SendblueSenderIdentities,
} from "./schemas.js";
import type { SendblueConfig as SendblueConfigType } from "./schemas.js";

const apiKeyConfig = Config.redacted("BUNDJIL_SENDBLUE_API_KEY");
const apiSecretConfig = Config.redacted("BUNDJIL_SENDBLUE_API_SECRET");
const webhookSecretConfig = Config.redacted("BUNDJIL_SENDBLUE_WEBHOOK_SECRET");
const routingKeyConfig = Config.redacted("BUNDJIL_SENDBLUE_ROUTING_KEY");
const fromNumberConfig = Config.schema(
  E164PhoneNumber,
  "BUNDJIL_SENDBLUE_FROM_NUMBER"
);
const senderIdentitiesConfig = Config.redacted(
  "BUNDJIL_SENDBLUE_SENDER_IDENTITIES"
);
const replayStoreUrlConfig = Config.redacted(
  "BUNDJIL_SENDBLUE_REPLAY_STORE_URL"
).pipe(Config.orElse(() => Config.redacted("KV_REST_API_URL")));
const replayStoreTokenConfig = Config.redacted(
  "BUNDJIL_SENDBLUE_REPLAY_STORE_TOKEN"
).pipe(Config.orElse(() => Config.redacted("KV_REST_API_TOKEN")));
const replayStorePrefixConfig = Config.nonEmptyString(
  "BUNDJIL_SENDBLUE_REPLAY_STORE_PREFIX"
);
const replayStoreTtlSecondsConfig = Config.schema(
  Schema.Int.check(Schema.isGreaterThan(0)),
  "BUNDJIL_SENDBLUE_REPLAY_STORE_TTL_SECONDS"
);
const replayStoreLeaseSecondsConfig = Config.schema(
  Schema.Int.check(Schema.isGreaterThan(0)),
  "BUNDJIL_SENDBLUE_REPLAY_STORE_LEASE_SECONDS"
);
const allowedServicesConfig = Config.schema(
  Schema.Array(Schema.Literals(["iMessage", "SMS", "RCS"])),
  "BUNDJIL_SENDBLUE_ALLOWED_SERVICES"
).pipe(Config.withDefault(["iMessage"]));
const testModeConfig = Config.option(
  Config.literal("true", "BUNDJIL_SENDBLUE_TEST_MODE")
);
const testApiBaseUrlConfig = Config.option(
  Config.url("BUNDJIL_SENDBLUE_TEST_API_BASE_URL")
);

export class SendblueConfigService extends Context.Service<
  SendblueConfigService,
  SendblueConfigType
>()("@bundjil/agent/SendblueConfig") {}

export const loadSendblueConfig = Effect.gen(
  function* loadSendblueConfigFromProvider() {
    const values = yield* Effect.all({
      allowedServices: allowedServicesConfig,
      apiKey: apiKeyConfig,
      apiSecret: apiSecretConfig,
      fromNumber: fromNumberConfig,
      replayStoreLeaseSeconds: replayStoreLeaseSecondsConfig,
      replayStorePrefix: replayStorePrefixConfig,
      replayStoreToken: replayStoreTokenConfig,
      replayStoreTtlSeconds: replayStoreTtlSecondsConfig,
      replayStoreUrl: replayStoreUrlConfig,
      routingKey: routingKeyConfig,
      senderIdentities: senderIdentitiesConfig,
      testApiBaseUrl: testApiBaseUrlConfig,
      testMode: testModeConfig,
      webhookSecret: webhookSecretConfig,
    });
    const senderIdentities = yield* Schema.decodeUnknownEffect(
      Schema.fromJsonString(SendblueSenderIdentities)
    )(Redacted.value(values.senderIdentities));
    const apiBaseUrl = yield* Option.match(values.testApiBaseUrl, {
      onNone: () => Effect.succeed(new URL("https://api.sendblue.com")),
      onSome: (url) =>
        Option.match(values.testMode, {
          onNone: () =>
            Effect.fail(
              new SendblueConfigError({
                message: "The Sendblue test API URL requires test mode.",
              })
            ),
          onSome: () => Effect.succeed(url),
        }),
    });

    return yield* Schema.decodeUnknownEffect(SendblueConfig)({
      allowedServices: values.allowedServices,
      apiBaseUrl,
      apiKey: values.apiKey,
      apiSecret: values.apiSecret,
      fromNumber: values.fromNumber,
      replayStore: {
        leaseSeconds: values.replayStoreLeaseSeconds,
        prefix: values.replayStorePrefix,
        token: values.replayStoreToken,
        ttlSeconds: values.replayStoreTtlSeconds,
        url: values.replayStoreUrl,
      },
      routingKey: values.routingKey,
      senderIdentities,
      webhookSecret: values.webhookSecret,
    });
  }
).pipe(
  Effect.mapError(
    () =>
      new SendblueConfigError({
        message: "Unable to load Sendblue configuration.",
      })
  ),
  Effect.withSpan("SendblueConfig.load")
);

export const SendblueConfigLive = Layer.effect(
  SendblueConfigService,
  loadSendblueConfig
);
import { Layer } from "effect";
import { FetchHttpClient } from "effect/unstable/http";

import { SendblueChannelLive } from "./channel.service.js";
import { SendblueClientLive } from "./client.service.js";
import { SendblueConfigLive } from "./config.js";
import { SendblueIdentityDirectoryLive } from "./identity-directory.service.js";
import { SendblueReplayStoreUpstashLive } from "./replay-store.service.js";
import { SendblueSessionRouterLive } from "./session-router.service.js";
import { SendblueWebhookVerifierLive } from "./webhook-verifier.service.js";

const sendblueServicesLive = Layer.mergeAll(
  SendblueWebhookVerifierLive,
  SendblueIdentityDirectoryLive,
  SendblueSessionRouterLive,
  SendblueReplayStoreUpstashLive,
  SendblueClientLive
).pipe(
  Layer.provideMerge(SendblueConfigLive),
  Layer.provideMerge(FetchHttpClient.layer)
);

export const SendblueChannelRuntimeLive = SendblueChannelLive.pipe(
  Layer.provideMerge(sendblueServicesLive)
);
import { Context, Effect, Layer, Match, Schema } from "effect";

import { SendblueClient } from "./client.service.js";
import type { SendblueClientError } from "./client.service.js";
import { SendblueConfigService } from "./config.js";
import {
  SendblueRequestError,
  SendblueRoutingError,
  SendblueWebhookSchemaError,
} from "./errors.js";
import type {
  SendblueReplayStoreError,
  SendblueWebhookAuthenticationError,
} from "./errors.js";
import { SendblueIdentityDirectory } from "./identity-directory.service.js";
import { SendblueReplayStore } from "./replay-store.service.js";
import {
  SendblueCompletedMessage,
  SendblueInboundMessage,
  SendblueSendMessageInput,
} from "./schemas.js";
import type {
  SendblueCompletedMessage as SendblueCompletedMessageType,
  SendblueCompletedMessageResult,
  SendblueInboundDecision,
  SendblueInboundDispatchDecision,
} from "./schemas.js";
import { SendblueSessionRouter } from "./session-router.service.js";
import { SendblueWebhookVerifier } from "./webhook-verifier.service.js";

export interface SendblueChannelShape {
  readonly authorizeAndClaimInbound: (
    request: Request
  ) => Effect.Effect<
    SendblueInboundDecision,
    | SendblueWebhookAuthenticationError
    | SendblueWebhookSchemaError
    | SendblueReplayStoreError
    | SendblueRoutingError
  >;
  readonly dispatchAcceptedInbound: (
    decision: SendblueInboundDispatchDecision,
    send: () => Promise<unknown>
  ) => Effect.Effect<void, SendblueReplayStoreError | SendblueRoutingError>;
  readonly deliverCompletedMessage: (
    input: SendblueCompletedMessageType
  ) => Effect.Effect<
    SendblueCompletedMessageResult,
    SendblueClientError | SendblueReplayStoreError | SendblueRoutingError
  >;
}

export class SendblueChannel extends Context.Service<
  SendblueChannel,
  SendblueChannelShape
>()("@bundjil/agent/SendblueChannel") {}

export const authorizeAndClaimInbound = Effect.fn(
  "SendblueChannel.authorizeAndClaimInbound"
)(function* (request: Request) {
  const verifier = yield* SendblueWebhookVerifier;
  const config = yield* SendblueConfigService;
  const identities = yield* SendblueIdentityDirectory;
  const replay = yield* SendblueReplayStore;
  const router = yield* SendblueSessionRouter;

  yield* verifier.verify(request.headers);
  const body = yield* Effect.tryPromise({
    try: () => request.text(),
    catch: () =>
      new SendblueWebhookSchemaError({
        boundary: "SendblueInboundMessage",
        message: "Unable to read the Sendblue webhook body.",
      }),
  });
  if (body.length > 131_072) {
    return yield* new SendblueWebhookSchemaError({
      boundary: "SendblueInboundMessage",
      message: "The Sendblue webhook body is too large.",
    });
  }
  const inbound = yield* Schema.decodeUnknownEffect(
    Schema.fromJsonString(SendblueInboundMessage)
  )(body).pipe(
    Effect.mapError(
      () =>
        new SendblueWebhookSchemaError({
          boundary: "SendblueInboundMessage",
          message: "The Sendblue webhook body is invalid.",
        })
    )
  );

  const ignored = Match.value(inbound).pipe(
    Match.when({ is_typing: true }, () => "typing" as const),
    Match.when({ direction: "outbound" }, () => "outbound" as const),
    Match.when({ is_outbound: true }, () => "outbound" as const),
    Match.when(
      ({ status }) => status !== "RECEIVED",
      () => "statusNotReceived" as const
    ),
    Match.when(
      ({ group_id }) => group_id !== undefined && group_id.length > 0,
      () => "group" as const
    ),
    Match.when(
      ({ media_url, media_urls }) =>
        (media_url !== undefined && media_url.length > 0) ||
        (media_urls !== undefined && media_urls.length > 0),
      () => "media" as const
    ),
    Match.when(
      ({ content }) => content.trim().length === 0,
      () => "empty" as const
    ),
    Match.when(
      ({ service }) => !config.allowedServices.includes(service),
      () => "serviceNotAllowed" as const
    ),
    Match.when(
      ({ sendblue_number, to_number }) =>
        sendblue_number !== config.fromNumber &&
        to_number !== config.fromNumber,
      () => "lineMismatch" as const
    ),
    Match.when(
      ({ from_number }) => from_number === config.fromNumber,
      () => "loop" as const
    ),
    Match.orElse(() => null)
  );
  if (ignored !== null) {
    return {
      _tag: "Ignore",
      outcome: { reason: ignored },
    } satisfies SendblueInboundDecision;
  }

  const identity = yield* identities
    .resolve(inbound.from_number)
    .pipe(Effect.catchTag("SendblueSenderNotAllowedError", () => Effect.void));
  if (identity === undefined) {
    return {
      _tag: "Ignore",
      outcome: { reason: "senderNotAllowed" },
    } satisfies SendblueInboundDecision;
  }
  const continuationToken = yield* router.route(
    inbound.from_number,
    config.fromNumber
  );
  const claimed = yield* replay.claimInbound(inbound.message_handle);
  if (claimed.status === "duplicate") {
    return { _tag: "Duplicate" } satisfies SendblueInboundDecision;
  }
  return {
    _tag: "Dispatch",
    auth: {
      attributes: { channel: "sendblue" },
      authenticator: "sendblue",
      principalId: identity.principalId,
      principalType: "user",
    },
    claim: claimed.claim,
    continuationToken,
    message: inbound.content.trim(),
    state: {
      conversationKey: continuationToken,
      principalId: identity.principalId,
      sendblueNumber: config.fromNumber,
      senderNumber: inbound.from_number,
    },
  } satisfies SendblueInboundDecision;
});

export const dispatchAcceptedInbound = Effect.fn(
  "SendblueChannel.dispatchAcceptedInbound"
)(function* (
  decision: SendblueInboundDispatchDecision,
  send: () => Promise<unknown>
) {
  const replay = yield* SendblueReplayStore;
  yield* Effect.tryPromise({
    try: send,
    catch: () =>
      new SendblueRoutingError({
        message: "Unable to dispatch the Sendblue message to Eve.",
      }),
  }).pipe(
    Effect.catchTag("SendblueRoutingError", (error) =>
      replay.retryable(decision.claim).pipe(Effect.andThen(Effect.fail(error)))
    )
  );
  return yield* replay
    .complete(decision.claim)
    .pipe(
      Effect.catchTag("SendblueReplayStoreError", (completeError) =>
        replay
          .uncertain(decision.claim)
          .pipe(Effect.andThen(Effect.fail(completeError)))
      )
    );
});

export const deliverCompletedMessage = Effect.fn(
  "SendblueChannel.deliverCompletedMessage"
)(function* (input: SendblueCompletedMessageType) {
  const completed = yield* Schema.decodeUnknownEffect(SendblueCompletedMessage)(
    input
  ).pipe(
    Effect.mapError(
      () =>
        new SendblueRoutingError({
          message: "The completed Eve message is invalid.",
        })
    )
  );
  if (
    completed.finishReason === "tool-calls" ||
    completed.message === null ||
    completed.message.trim().length === 0
  ) {
    return "ignored";
  }
  const replay = yield* SendblueReplayStore;
  const client = yield* SendblueClient;
  const claimed = yield* replay.claimOutbound({
    sequence: completed.sequence,
    sessionId: completed.sessionId,
    stepIndex: completed.stepIndex,
    turnId: completed.turnId,
  });
  if (claimed.status === "duplicate") {
    return "duplicate";
  }
  return yield* Schema.decodeUnknownEffect(SendblueSendMessageInput)({
    content: completed.message.trim(),
    from_number: completed.state.sendblueNumber,
    number: completed.state.senderNumber,
  }).pipe(
    Effect.mapError(
      () =>
        new SendblueRequestError({
          message: "The completed Eve message cannot be sent by Sendblue.",
          operation: "sendMessage",
          reason: "requestEncoding",
        })
    ),
    Effect.flatMap(client.sendMessage),
    Effect.tap((success) =>
      replay
        .complete(claimed.claim, {
          providerMessageHandle: success.message_handle,
        })
        .pipe(
          Effect.catchTag("SendblueReplayStoreError", (completeError) =>
            replay
              .uncertain(claimed.claim)
              .pipe(Effect.andThen(Effect.fail(completeError)))
          )
        )
    ),
    Effect.as("delivered" as const),
    Effect.catchTag("SendblueDeliveryUncertainError", (error) =>
      replay.uncertain(claimed.claim).pipe(Effect.andThen(Effect.fail(error)))
    ),
    Effect.catchTag("SendblueRequestError", (error) =>
      replay.retryable(claimed.claim).pipe(Effect.andThen(Effect.fail(error)))
    ),
    Effect.catchTag("SendblueResponseError", (error) =>
      (error.reason === "malformedResponse"
        ? replay.uncertain(claimed.claim)
        : replay.retryable(claimed.claim)
      ).pipe(Effect.andThen(Effect.fail(error)))
    )
  );
});

export const SendblueChannelLive = Layer.effect(
  SendblueChannel,
  Effect.gen(function* makeSendblueChannel() {
    const client = yield* SendblueClient;
    const config = yield* SendblueConfigService;
    const identities = yield* SendblueIdentityDirectory;
    const replay = yield* SendblueReplayStore;
    const router = yield* SendblueSessionRouter;
    const verifier = yield* SendblueWebhookVerifier;
    return SendblueChannel.of({
      authorizeAndClaimInbound: (request) =>
        authorizeAndClaimInbound(request).pipe(
          Effect.provideService(SendblueWebhookVerifier, verifier),
          Effect.provideService(SendblueConfigService, config),
          Effect.provideService(SendblueIdentityDirectory, identities),
          Effect.provideService(SendblueReplayStore, replay),
          Effect.provideService(SendblueSessionRouter, router)
        ),
      deliverCompletedMessage: (input) =>
        deliverCompletedMessage(input).pipe(
          Effect.provideService(SendblueClient, client),
          Effect.provideService(SendblueReplayStore, replay)
        ),
      dispatchAcceptedInbound: (decision, send) =>
        dispatchAcceptedInbound(decision, send).pipe(
          Effect.provideService(SendblueReplayStore, replay)
        ),
    });
  })
);


===== NEXT =====

keeps one error to make the service shape readable.

Provider wire Schemas deliberately retain documented names such as
`from_number`, `to_number`, and `message_handle`. If the implementation needs a
camelCase domain view, define one Schema transformation at the provider
boundary; do not add handwritten request/response mappers.

The Eve channel creates one app-owned `ManagedRuntime` at module scope and
invokes it only from the route/event adapter. Services never call
`Effect.runPromise`, construct their own runtime, or provide live Layers inside
primary operations.

## Configuration

Load configuration with Effect `Config`, `ConfigProvider.fromEnv()`,
`Config.redacted`, and Schema validation. Required Preview/Production variables
are target-scoped:

- `BUNDJIL_SENDBLUE_API_KEY` (redacted);
- `BUNDJIL_SENDBLUE_API_SECRET` (redacted);
- `BUNDJIL_SENDBLUE_WEBHOOK_SECRET` (redacted, mandatory and fail-closed);
- `BUNDJIL_SENDBLUE_FROM_NUMBER` (E.164);
- `BUNDJIL_SENDBLUE_SENDER_IDENTITIES` (redacted schema-encoded mapping from
  E.164 sender to stable principal id);
- `BUNDJIL_SENDBLUE_ROUTING_KEY` (redacted key for conversation digests);
- replay-store Upstash URL/token/prefix and TTL/lease settings;
- optional allowed service set, defaulting to only `iMessage`.

The provider API base URL defaults to `https://api.sendblue.com` and may be
overridden only in tests/local fixtures. The channel must not silently enable
itself when any required secret, identity mapping, line, or replay store is
missing.

## Webhook Authentication And Parsing

The route is `POST /eve/v1/sendblue/webhook` unless installed Eve route
resolution proves a different non-conflicting path is required.

Processing order is mandatory:

1. Require `POST`, HTTPS at the deployed edge, and a configured webhook secret.
2. Read `sb-signing-secret` and compare its bytes with the configured secret in
   constant time. Normalize neither secret. Length mismatch is an auth failure.
3. Return sanitized `401` on missing/mismatch. Do not parse or log the body.
4. Read the body once, enforce a small maximum size, and decode it with
   `Schema.fromJsonString(SendblueInboundMessage)` or the equivalent Effect
   Schema JSON codec.
5. Classify direction/status/service/group/media/content using `Match` or
   schema unions. Only a direct, text-bearing, non-outbound `RECEIVED` event for
   an allowed service can continue.
6. Verify `to_number`/`sendblue_number` corresponds to the configured line and
   `from_number` is not the Sendblue line. This prevents route confusion and
   outbound loops.
7. Map the authenticated sender through `SendblueIdentityDirectory`. Unknown
   senders receive a `2xx` ignored acknowledgement, no Eve session, and a
   sanitized metric; do not disclose enrollment policy over the webhook.

The route returns `2xx` for valid ignored events and already-claimed duplicate
events. It returns `400` for authenticated malformed payloads, `401` for auth
failure, and `503` when the replay store cannot safely make a claim. The exact
accepted status (`200` or `202`) must be verified against Sendblue and Eve
behavior and used consistently.

## Replay Protection

Process-local `Map`/`Set` state is forbidden. Vercel instances are concurrent
and ephemeral.

`SendblueReplayStore` is an app-owned Effect service with explicit memory and
Upstash live Layers. Its live `claim` operation must be a single atomic provider
operation such as Redis `SET key value NX EX`, not the default non-atomic
get-then-set implementation of Effect `KeyValueStore.modify`.

Inbound claim key:

```text
sendblue:inbound:<environment>:<message_handle_digest>
```

Claim before calling Eve `send`. If the durable Eve dispatch fails before a
session is accepted, transition the claim to a bounded retryable state or
release it through a compare-and-delete lease. If dispatch is accepted, mark it
complete and retain it longer than Sendblue's retry horizon. Never clear a
completed claim merely because outbound delivery later fails.

Outbound claim key uses stable Eve event coordinates available in
`message.completed`:

```text
sendblue:outbound:<environment>:<session_id>:<turn_id>:<step_index>:<sequence>
```

Claim before `POST /api/send-message`. On a successful Sendblue response,
persist the provider `message_handle` and terminal state. On an indeterminate
network/timeout result, mark the claim `uncertain`, emit an alert, and do not
automatically resend. An operator can inspect Sendblue by the safe correlation
record before deciding to retry. This trades possible omission for protection
against duplicate personal messages when the provider accepted a request but
the response was lost.

